import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`landscaping-quote`,heroTitle:`Build landscaping quotes in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans, scopes the materials and labor, and drafts a client-ready landscaping quote automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your property plan`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded a landscaping scope, site plan, or client notes. Build a complete landscaping quote. (1) Extract the property areas, hardscape and softscape scope, materials, plantings, irrigation needs, and site constraints from the uploaded files. (2) Estimate labor, materials, equipment, hauling, and subcontractor needs for each phase of the project. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight optional enhancements, maintenance upsells, or seasonal considerations where relevant. (5) Deliver a polished landscaping quote with scope summary, line-item pricing, and next steps.`,heroOverlaySteps:[`Extracting property scope, materials, plantings, and site constraints from your files`,`Planning labor, equipment, hauling, and installation by project phase`,`Building pricing options with alternates, upgrades, and seasonal considerations`,`Client-ready landscaping quote with scope summary, ready to send`],generatingSteps:[`Reading the uploaded site plan, scope notes, and property details`,`Designing an agent to organize the work into materials, labor, and project phases`,`Configuring pricing logic for upgrades, assumptions, and maintenance opportunities`,`Preparing a landscaping quote with line items, scope summary, and next steps`],featureSectionTitle:`From site plan to client-ready quote`,featureCardTitles:[`Connects to your field workflow`,`Quotes built around scope and seasonality`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, site notes, and internal planning workflows stay connected so quoting and revisions move faster.`,`Materials. Labor. Alternates. Maintenance upsells. Computer gives your team a landscaping quote draft that is ready for client review.`],capabilitySectionTitle:`Your quoting desk, on autopilot`,capabilitySectionSubtitle:`Upload the plan, get back a landscaping quote built around the real property scope.`,capabilityCards:[{title:`Property Scope Analysis`,description:`Computer can extract beds, turf, hardscape areas, irrigation needs, and site constraints from property plans and uploaded notes.`},{title:`Materials & Plant Planning`,description:`Computer can organize plantings, hardscape materials, irrigation components, and equipment needs so the quote reflects the real job.`},{title:`Labor & Margin Model`,description:`Computer can turn the project into phase-based pricing with assumptions, alternates, and room for upgrades or maintenance add-ons.`},{title:`Connect Your Tools`,description:`Computer can keep quote drafts organized across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Packages`,description:`Computer can remember your preferred materials, planting assumptions, and pricing structure across sessions so quotes stay consistent.`},{title:`Seasonal Follow-Up`,description:`Computer can suggest maintenance plans and seasonal follow-up work so the quote supports both the project and the recurring revenue opportunity.`}]});export{t as default};
